// Determine stage transitions based on PARA methodology
// Jots → Tasks → Projects → Areas/Resources → Archives

function shouldTransitionStage(item) {
  const { stage, score, color_code, updated_at, created_at } = item;
  const ageInDays = (Date.now() - new Date(created_at).getTime()) / (1000 * 60 * 60 * 24);
  const lastUpdatedDays = (Date.now() - new Date(updated_at).getTime()) / (1000 * 60 * 60 * 24);

  let newStage = stage;
  let reason = '';

  switch (stage) {
    case 'jots':
      // Jots become tasks when they have enough detail or high priority
      if ((score >= 5 && color_code === 'gold') || 
          ageInDays > 7 || 
          (item.title && item.title.length > 20) ||
          item.due_date) {
        newStage = 'tasks';
        reason = 'Jot matured into actionable task';
      }
      break;

    case 'tasks':
      // Tasks become projects when they have dependencies or scope
      if (score >= 8 || 
          ageInDays > 14 || 
          item.blocks_others || 
          (item.affected_areas && item.affected_areas.length > 1)) {
        newStage = 'projects';
        reason = 'Task evolved into project with dependencies';
      }
      break;

    case 'projects':
      // Projects move to areas/resources when completed or stable
      if (lastUpdatedDays > 30 || 
          (item.content && item.content.toLowerCase().includes('complete'))) {
        // Check if it's more of an area (ongoing) or resource (reference)
        const isArea = item.title.toLowerCase().includes('system') || 
                      item.title.toLowerCase().includes('process') || 
                      item.title.toLowerCase().includes('maintenance');
        newStage = isArea ? 'areas' : 'resources';
        reason = `Project completed, moved to ${newStage}`;
      }
      break;

    case 'areas':
    case 'resources':
      // Move to archives after 6 months of inactivity
      if (lastUpdatedDays > 180) {
        newStage = 'archives';
        reason = 'Archived due to inactivity';
      }
      break;
  }

  return newStage !== stage ? { newStage, reason } : null;
}

// Process items and identify transitions
const transitions = [];
$input.all().forEach(item => {
  const transition = shouldTransitionStage(item);
  if (transition) {
    transitions.push({
      ...item,
      ...transition,
      transition_timestamp: new Date().toISOString()
    });
  }
});

return transitions;

// Helper function to map PARA stages to Linear states
// This would need to be customized based on your Linear workspace
function getLinearStateIdForStage(stage) {
  const stageMapping = {
    'jots': process.env.LINEAR_BACKLOG_STATE_ID,
    'tasks': process.env.LINEAR_TODO_STATE_ID,
    'projects': process.env.LINEAR_IN_PROGRESS_STATE_ID,
    'areas': process.env.LINEAR_REVIEW_STATE_ID,
    'resources': process.env.LINEAR_REVIEW_STATE_ID,
    'archives': process.env.LINEAR_DONE_STATE_ID
  };
  return stageMapping[stage] || stageMapping['tasks'];
}

// This function is called by the Linear node
return getLinearStateIdForStage($json.newStage);
